<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>Bouncing Ball Playground</title>
<style>
  body {
    margin: 0;
    padding: 20px;
    background-color: #1a1a1a; /* Dark Theme */
    color: #f5f5f5;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
  }

  .container {
    display: flex;
    flex-direction: column;
    gap: 20px;
    text-align: center;
  }

  canvas#sim {
    background-color: #252525;
    border-radius: 8px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.6);
    cursor: crosshair; /* Satisfying to click */

    /* Ensure rendered size is at least 400x400 CSS pixels */
    min-width: 400px;
    min-height: 400px;
    width: 600px; 
    height: 600px;

    display: block;
  }

  .controls {
    display: flex;
    justify-content: center;
    gap: 15px;
  }

  button {
    padding: 12px 24px;
    background-color: #3a3a3a;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 16px;
    cursor: pointer;
    transition: background-color 0.2s ease, transform 0.1s;
  }

  button:hover {
    background-color: #4a4a4a;
  }

  button:active {
    transform: scale(0.95); /* Satisfying to click */
  }
</style>
</head>
<body>
<div class="container">
  <canvas id="sim"></canvas>

  <div class="controls">
    <button id="drop">Drop Ball</button>
    <button id="play">Play Animation</button>
    <button id="clear">Clear Balls</button>
  </div>
</div>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');

  // Dimensions in pixels (intrinsic). Must be >= 400x400.
  const SIM_W = 600;
  const SIM_H = 600;

  canvas.width = SIM_W;
  canvas.height = SIM_H;

  // Physics Constants
  const GRAVITY = 0.8; 
  const RESTITUTION = 0.75; 

  let balls = [];
  let isRunning = false;
  let animationFrameId = null;

  function loop() {
    if (isRunning) {
      window.sim.step(); // Advance sim one step and redraw
      animationFrameId = requestAnimationFrame(loop);
    } else {
      cancelAnimationFrame(animationFrameId);
    }
  }

  document.getElementById('play').addEventListener('click', () => {
    isRunning = !isRunning;
    const btn = document.getElementById('play');

    if (isRunning) {
      loop(); // Start the animation loop
      btn.textContent = "Pause Animation";
    } else {
      cancelAnimationFrame(animationFrameId); 
      btn.textContent = "Play Animation";
    }
  });

  document.getElementById('drop').addEventListener('click', () => {
    window.sim.addBall();
  });

  document.getElementById('clear').addEventListener('click', () => {
    window.sim.clear();
  });

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();

    // Calculate scaling factors if CSS size != intrinsic buffer
    // Since our CSS matches intrinsic, scaleX/y should be ~1 unless scaled via media.
    const scaleX = SIM_W / rect.width;
    const scaleY = SIM_H / rect.height;

    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;

    window.sim.addBall(x, y);
  });

  // Expose API as requested on global window object
  window.sim = {
    get w() { return SIM_W; },
    get h() { return SIM_H; },

    balls: () => [...balls], 

    addBall: (x=SIM_W/2, y=SIM_H/4, vx=0, vy=0, r) => {
      if (!r) {
        // Random radius between 15 and 30 for visibility
        r = Math.random() * 15 + 15;
      }

      // Clamp initial position to canvas bounds
      x = Math.max(r, Math.min(x, SIM_W - r));
      y = Math.max(r, Math.min(y, SIM_H - r));

      balls.push({x, y, vx, vy, r});
    },

    clear: () => {
      balls = [];
    },

    step: (dt=1) => {
      // Update physics for each ball

      let needsDraw = false;

      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];

        // Gravity accelerates every ball downward each step (increase vy)
        b.vy += GRAVITY * dt;

        // Update Position
        b.x += b.vx * dt;
        b.y += b.vy * dt;

        // --- Horizontal Bounds Check (Left/Right Walls) ---
        if (b.x + b.r > SIM_W) {
          // Clamp inside and reverse velocity component with energy loss
          b.x = SIM_W - b.r; 
          b.vx *= -RESTITUTION; 
          needsDraw = true;
        } else if (b.x - b.r < 0) {
          b.x = b.r; 
          b.vx *= -RESTITUTION;
          needsDraw = true;
        }

        // --- Vertical Bounds Check (Floor/Ceiling) ---
        // Note: Checked separately to handle corner collisions properly in one step.
        if (b.y + b.r > SIM_H) {
          b.y = SIM_H - b.r; 
          b.vy *= -RESTITUTION;
          needsDraw = true;

        } else if (b.y - b.r < 0) {
          b.y = b.r; 
          b.vy *= -RESTITUTION;
          needsDraw = true;
        }
      }

      // Redraw Canvas & Balls
      ctx.clearRect(0, 0, SIM_W, SIM_H);

      for (let b of balls) {
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);

        // Visibly drawn: Bright Cyan on Dark Background
        ctx.fillStyle = '#00E5FF'; 
        ctx.fill();
        ctx.strokeStyle = 'white';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    }
  };

})();
</script>
</body>
</html>
